type Toast = { message: string; tone?: 'success' | 'error' }
type AppContextValue = { version: number; refresh: () => void; toast: (message: string, tone?: Toast['tone']) => void }
const appDefaults: AppContextValue = { version: 0, refresh: () => undefined, toast: () => undefined }
const AppContext = createContext<AppContextValue>(appDefaults)
const useApp = () => useContext(AppContext)

function AppShell() {
  const [version, setVersion] = useState(0)
  const [notice, setNotice] = useState<Toast | null>(null)
  const refresh = useCallback(() => setVersion(item => item + 1), [])
  const toast = useCallback((message: string, tone: Toast['tone'] = 'success') => {
    setNotice({ message, tone })
    window.setTimeout(() => setNotice(null), 3600)
  }, [])

  useEffect(() => {
    const onOnline = async () => {
      if (supabaseConfigured) {
        const result = await syncNow()
        refresh()
        if (result.ok && result.pending === 0) toast('Conexão restabelecida. Dados sincronizados.')
      }
    }
    window.addEventListener('online', onOnline)
    return () => window.removeEventListener('online', onOnline)
  }, [refresh, toast])

  return <AppContext.Provider value={{ version, refresh, toast }}>
    <BrowserRouter>
      <Layout>
        <Routes>
          <Route path="/" element={<DashboardPage />} />
          <Route path="/clients" element={<ClientsPage />} />
          <Route path="/clients/:clientId" element={<ClientDetailPage />} />
          <Route path="/visits/new" element={<VisitEditorPage />} />
          <Route path="/visits/:visitId" element={<VisitEditorPage />} />
          <Route path="/history" element={<HistoryPage />} />
          <Route path="/settings" element={<SettingsPage />} />
          <Route path="*" element={<DashboardPage />} />
        </Routes>
      </Layout>
    </BrowserRouter>
    {notice && <div className={`fixed bottom-24 left-4 right-4 z-[60] mx-auto max-w-md rounded-xl px-4 py-3 text-sm font-medium text-white shadow-xl ${notice.tone === 'error' ? 'bg-red-600' : 'bg-brand-700'}`}>{notice.message}</div>}
  </AppContext.Provider>
}

function Layout({ children }: { children: ReactNode }) {
  const [open, setOpen] = useState(false)
  const nav = [
    ['/', 'Painel', BarChart3], ['/clients', 'Clientes', Users], ['/visits/new', 'Nova visita', Plus], ['/history', 'Histórico', History], ['/settings', 'Configurações', Settings]
  ] as const
  const content = <>
    <div className="flex items-center gap-3 border-b border-emerald-950/5 bg-white px-4 py-3 lg:hidden">
      <button className="btn-ghost min-h-9 px-2" onClick={() => setOpen(true)} aria-label="Abrir menu"><Menu size={22} /></button>
      <Brand />
      <div className="ml-auto"><SyncIndicator /></div>
    </div>
    <div className="min-h-screen lg:pl-64">
      <aside className={`fixed inset-y-0 left-0 z-50 flex w-64 flex-col border-r border-emerald-950/5 bg-white p-4 shadow-xl transition-transform lg:translate-x-0 lg:shadow-none ${open ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="mb-8 flex items-center justify-between"><Brand /><button className="btn-ghost px-2 lg:hidden" onClick={() => setOpen(false)}><X size={20} /></button></div>
        <nav className="space-y-1" onClick={() => setOpen(false)}>{nav.map(([to, label, Icon]) => <NavLink key={to} to={to} end={to === '/'} className={({ isActive }) => `nav-link ${isActive ? 'nav-link-active' : ''}`}><Icon size={19} />{label}</NavLink>)}</nav>
        <div className="mt-auto border-t border-slate-100 pt-4"><SyncIndicator /></div>
      </aside>
      {open && <button aria-label="Fechar menu" className="fixed inset-0 z-40 bg-slate-900/35 lg:hidden" onClick={() => setOpen(false)} />}
      <main className="mx-auto max-w-7xl px-4 py-5 pb-24 sm:px-6 lg:px-8 lg:py-8 lg:pb-8">{children}</main>
      <nav className="fixed inset-x-0 bottom-0 z-40 flex justify-around border-t border-slate-200 bg-white px-1 py-1 pb-[max(0.25rem,env(safe-area-inset-bottom))] lg:hidden">
        {nav.slice(0, 4).map(([to, label, Icon]) => <NavLink key={to} to={to} end={to === '/'} className={({ isActive }) => `flex min-w-0 flex-1 flex-col items-center gap-0.5 rounded-lg px-1 py-1.5 text-[10px] font-medium ${isActive ? 'text-brand-700' : 'text-slate-500'}`}><Icon size={19}/><span className="truncate">{label}</span></NavLink>)}
      </nav>
    </div>
  </>
  return content
}

function Brand() { return <div className="flex items-center gap-2.5"><div className="grid h-9 w-9 place-items-center rounded-xl bg-brand-600 text-white"><Leaf size={20}/></div><div><div className="font-bold leading-none text-brand-800">ENGEDROP</div><div className="mt-0.5 text-[10px] font-semibold tracking-[0.18em] text-slate-400">CAMPO</div></div></div> }

function SyncIndicator() {
  const { version, refresh, toast } = useApp()
  const [pending, setPending] = useState(0)
  const [working, setWorking] = useState(false)
  const [online, setOnline] = useState(isOnline())
  useEffect(() => { pendingSyncCount().then(setPending); setOnline(isOnline()) }, [version])
  useEffect(() => { const set = () => setOnline(isOnline()); window.addEventListener('online', set); window.addEventListener('offline', set); return () => { window.removeEventListener('online', set); window.removeEventListener('offline', set) } }, [])
  const run = async () => { setWorking(true); const result = await syncNow(); setWorking(false); setPending(result.pending); refresh(); toast(result.message, result.ok ? 'success' : 'error') }
  if (!supabaseConfigured) return <NavLink to="/settings" className="flex items-center gap-2 rounded-lg bg-amber-50 px-2.5 py-2 text-xs font-medium text-amber-800"><CloudOff size={15}/>Modo local</NavLink>
  return <button onClick={run} disabled={working || !online} className={`flex w-full items-center gap-2 rounded-lg px-2.5 py-2 text-left text-xs font-medium ${online ? 'bg-brand-50 text-brand-700 hover:bg-brand-100' : 'bg-slate-100 text-slate-500'}`}>
    {working ? <Loader2 className="animate-spin" size={15}/> : online ? <Cloud size={15}/> : <CloudOff size={15}/>} {working ? 'Sincronizando...' : !online ? 'Trabalhando offline' : pending ? `${pending} pendente(s)` : 'Sincronizado'}
  </button>
}

function PageHeader({ title, subtitle, actions }: { title: string; subtitle?: string; actions?: ReactNode }) { return <div className="mb-6 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><h1 className="text-2xl font-bold tracking-tight text-slate-900 sm:text-3xl">{title}</h1>{subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}</div>{actions && <div className="flex flex-wrap gap-2">{actions}</div>}</div> }
function Card({ children, className = '' }: { children: ReactNode; className?: string }) { return <section className={`card ${className}`}>{children}</section> }
function Modal({ title, children, onClose, wide = false }: { title: string; children: ReactNode; onClose: () => void; wide?: boolean }) { return <div className="fixed inset-0 z-50 flex items-end bg-slate-900/45 p-0 sm:items-center sm:justify-center sm:p-4"><div className={`max-h-[92vh] w-full overflow-y-auto rounded-t-3xl bg-white p-5 shadow-2xl sm:rounded-3xl sm:p-6 ${wide ? 'sm:max-w-3xl' : 'sm:max-w-lg'}`}><div className="mb-5 flex items-center justify-between"><h2 className="text-lg font-bold text-slate-900">{title}</h2><button className="btn-ghost min-h-9 px-2" onClick={onClose}><X size={19}/></button></div>{children}</div></div> }
function Empty({ title, description, action }: { title: string; description: string; action?: ReactNode }) { return <Card className="py-10 text-center"><Sprout className="mx-auto mb-3 text-brand-500" size={34}/><h3 className="font-semibold">{title}</h3><p className="mx-auto mt-1 max-w-md text-sm text-slate-500">{description}</p>{action && <div className="mt-4">{action}</div>}</Card> }
function StatusBadge({ status }: { status: Visit['status'] }) { return <span className={`rounded-full px-2.5 py-1 text-xs font-semibold ${status === 'finalized' ? 'bg-brand-100 text-brand-800' : 'bg-amber-100 text-amber-800'}`}>{status === 'finalized' ? 'Finalizada' : 'Rascunho'}</span> }

function useLoaded<T>(loader: () => Promise<T>, deps: unknown[] = []) {
  const { version } = useApp()
  const [data, setData] = useState<T | null>(null)
  const [loading, setLoading] = useState(true)
  useEffect(() => { let alive = true; setLoading(true); loader().then(result => { if (alive) setData(result) }).finally(() => { if (alive) setLoading(false) }); return () => { alive = false } }, [version, ...deps]) // eslint-disable-line react-hooks/exhaustive-deps
  return { data, loading, setData }
}

function DashboardPage() {
  const { data, loading } = useLoaded(dashboardData)
  const [clients, setClients] = useState<Client[]>([])
  useEffect(() => { db.clients.toArray().then(setClients) }, [data])
  const navigate = useNavigate()
  if (loading || !data) return <Loading />
  const metrics = [[Users, data.clients, 'Clientes'], [Building2, data.properties, 'Propriedades'], [MapPin, data.fields, 'Talhões'], [ClipboardList, data.visits, 'Visitas']] as const
  return <><PageHeader title="Bom trabalho no campo" subtitle="Acompanhe os atendimentos e continue de onde parou." actions={<button className="btn-primary" onClick={() => navigate('/visits/new')}><Plus size={18}/>Nova visita</button>}/>
    <div className="grid grid-cols-2 gap-3 sm:grid-cols-4 sm:gap-4">{metrics.map(([Icon, value, label]) => <Card key={label} className="p-4"><Icon className="mb-4 text-brand-600" size={22}/><div className="text-2xl font-bold">{value}</div><div className="mt-1 text-xs font-medium text-slate-500">{label}</div></Card>)}</div>
    <div className="mt-6 grid gap-6 lg:grid-cols-[1.4fr_.6fr]"><Card><div className="mb-4 flex items-center justify-between"><div><h2 className="font-bold">Últimas visitas</h2><p className="text-sm text-slate-500">Avaliações e rascunhos recentes</p></div><button className="btn-ghost px-2 text-brand-700" onClick={() => navigate('/history')}>Ver histórico</button></div>{data.recent.length ? <div className="divide-y divide-slate-100">{data.recent.map(visit => <button key={visit.id} onClick={() => navigate(`/visits/${visit.id}`)} className="flex w-full items-center gap-3 py-3 text-left transition hover:bg-brand-50"><div className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-brand-50 text-brand-700"><CalendarDays size={19}/></div><div className="min-w-0 flex-1"><div className="truncate font-semibold">{clients.find(client => client.id === visit.clientId)?.name ?? 'Cliente removido'}</div><div className="text-xs text-slate-500">{dateLabel(visit.date)}{visit.season ? ` • ${visit.season}` : ''}</div></div><StatusBadge status={visit.status}/></button>)}</div> : <div className="py-8 text-center text-sm text-slate-500">Nenhuma visita registrada ainda.</div>}</Card>
      <Card className="bg-brand-700 text-white"><Leaf size={28} className="mb-6 text-brand-100"/><h2 className="text-xl font-bold">Visita ágil, mesmo sem sinal.</h2><p className="mt-2 text-sm leading-relaxed text-brand-100">Registre dados, fotos e observações no campo. Tudo fica salvo no aparelho e sincroniza quando a internet retornar.</p><button className="btn mt-6 w-full bg-white text-brand-700 hover:bg-brand-50" onClick={() => navigate('/visits/new')}>Iniciar nova visita <Plus size={17}/></button></Card></div>
  </>
}

function ClientsPage() {
  const { data: clients, loading } = useLoaded(() => db.clients.orderBy('name').toArray())
  const [query, setQuery] = useState('')
  const [adding, setAdding] = useState(false)
  const shown = (clients ?? []).filter(client => !client.archived && `${client.name} ${client.document ?? ''} ${client.phone ?? ''}`.toLowerCase().includes(query.toLowerCase()))
  return <><PageHeader title="Clientes" subtitle="Cadastre produtores e acesse seu histórico técnico." actions={<button className="btn-primary" onClick={() => setAdding(true)}><Plus size={18}/>Novo cliente</button>}/>
    <div className="relative mb-5 max-w-xl"><Search className="absolute left-3 top-3 text-slate-400" size={18}/><input className="input pl-10" value={query} onChange={event => setQuery(event.target.value)} placeholder="Pesquisar por nome, documento ou telefone" /></div>
    {loading ? <Loading/> : shown.length ? <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">{shown.map(client => <ClientCard key={client.id} client={client}/>)}</div> : <Empty title="Nenhum cliente encontrado" description="Cadastre o primeiro produtor para começar a organizar as visitas." action={<button className="btn-primary" onClick={() => setAdding(true)}><Plus size={17}/>Cadastrar cliente</button>}/>} 
    {adding && <ClientForm onClose={() => setAdding(false)}/>}</>
}

function ClientCard({ client }: { client: Client }) { const navigate = useNavigate(); return <button onClick={() => navigate(`/clients/${client.id}`)} className="card group flex w-full items-center gap-3 text-left transition hover:-translate-y-0.5 hover:border-brand-200"><div className="grid h-11 w-11 shrink-0 place-items-center rounded-xl bg-brand-100 font-bold text-brand-700">{initials(client.name)}</div><div className="min-w-0"><div className="truncate font-bold group-hover:text-brand-700">{client.name}</div><div className="truncate text-sm text-slate-500">{client.phone ?? client.document ?? client.email ?? 'Sem dados complementares'}</div></div></button> }

function ClientForm({ client, onClose }: { client?: Client; onClose: () => void }) {
  const { refresh, toast } = useApp(); const [form, setForm] = useState<Partial<Client>>(client ?? { name: '' }); const [saving, setSaving] = useState(false)
  const submit = async (event: FormEvent) => { event.preventDefault(); if (!form.name?.trim()) return toast('Informe o nome do cliente.', 'error'); setSaving(true); await saveClient({ ...client, ...form, name: form.name.trim() } as NewEntity<Client>); refresh(); toast(client ? 'Cliente atualizado.' : 'Cliente cadastrado.'); onClose() }
  return <Modal title={client ? 'Editar cliente' : 'Novo cliente'} onClose={onClose}><form className="space-y-4" onSubmit={submit}><FieldLabel label="Nome do cliente / produtor *"><input autoFocus className="input" value={form.name ?? ''} onChange={e => setForm({...form, name:e.target.value})}/></FieldLabel><div className="grid gap-4 sm:grid-cols-2"><FieldLabel label="CPF / CNPJ"><input className="input" value={form.document ?? ''} onChange={e => setForm({...form, document:e.target.value})}/></FieldLabel><FieldLabel label="Telefone"><input className="input" inputMode="tel" value={form.phone ?? ''} onChange={e => setForm({...form, phone:e.target.value})}/></FieldLabel></div><FieldLabel label="E-mail"><input className="input" type="email" value={form.email ?? ''} onChange={e => setForm({...form, email:e.target.value})}/></FieldLabel><FieldLabel label="Observações"><textarea className="input min-h-20" value={form.notes ?? ''} onChange={e => setForm({...form, notes:e.target.value})}/></FieldLabel><div className="flex justify-end gap-2 pt-2"><button type="button" className="btn-ghost" onClick={onClose}>Cancelar</button><button className="btn-primary" disabled={saving}>{saving && <Loader2 size={16} className="animate-spin"/>}Salvar cliente</button></div></form></Modal>
}

function ClientDetailPage() {
  const { clientId = '' } = useParams(); const navigate = useNavigate(); const { refresh, toast } = useApp()
  const { data, loading } = useLoaded(async () => {
    const client = await db.clients.get(clientId); const properties = await db.properties.where('clientId').equals(clientId).toArray(); const fields = (await Promise.all(properties.map(p => db.fields.where('propertyId').equals(p.id).toArray()))).flat(); const visits = await db.visits.where('clientId').equals(clientId).reverse().sortBy('date'); return { client, properties, fields, visits }
  }, [clientId])
  const [propertyForm, setPropertyForm] = useState(false); const [fieldForProperty, setFieldForProperty] = useState<Property | null>(null); const [editingClient, setEditingClient] = useState(false)
  if (loading) return <Loading/>; if (!data?.client) return <Empty title="Cliente não encontrado" description="Este cadastro não está disponível neste dispositivo." action={<button className="btn-secondary" onClick={() => navigate('/clients')}>Voltar para clientes</button>}/>
  const { client, properties, fields, visits } = data
  return <><button className="btn-ghost mb-3 -ml-2 px-2" onClick={() => navigate('/clients')}><ChevronLeft size={18}/>Clientes</button><PageHeader title={client.name} subtitle={[client.phone, client.email].filter(Boolean).join(' • ') || 'Cadastro de produtor'} actions={<><button className="btn-secondary" onClick={() => setEditingClient(true)}><Pencil size={16}/>Editar</button><button className="btn-primary" onClick={() => navigate(`/visits/new?client=${client.id}`)}><Plus size={17}/>Nova visita</button></>}/>
  <div className="grid gap-6 xl:grid-cols-[1.1fr_.9fr]"><div className="space-y-6"><Card><div className="mb-4 flex items-center justify-between"><div><h2 className="font-bold">Propriedades e talhões</h2><p className="text-sm text-slate-500">Organize as áreas acompanhadas.</p></div><button className="btn-secondary" onClick={() => setPropertyForm(true)}><Plus size={16}/>Propriedade</button></div>{properties.length ? <div className="space-y-3">{properties.map(property => <div key={property.id} className="rounded-xl border border-slate-100 p-4"><div className="flex flex-wrap items-start justify-between gap-2"><div><h3 className="font-semibold">{property.name}</h3><p className="text-sm text-slate-500">{[property.city, property.state].filter(Boolean).join(' / ') || 'Localização não informada'}</p></div><button className="btn-secondary min-h-9 px-3" onClick={() => setFieldForProperty(property)}><Plus size={15}/>Talhão</button></div><div className="mt-3 flex flex-wrap gap-2">{fields.filter(field => field.propertyId === property.id).map(field => <span key={field.id} className="rounded-lg bg-brand-50 px-2.5 py-1.5 text-xs font-medium text-brand-800">{field.name}{field.areaHa ? ` • ${decimal(field.areaHa)} ha` : ''}</span>)}{!fields.some(field => field.propertyId === property.id) && <span className="text-xs text-slate-400">Nenhum talhão cadastrado</span>}</div></div>)}</div> : <div className="py-7 text-center text-sm text-slate-500">Adicione a primeira propriedade deste cliente.</div>}</Card>
  <Card><h2 className="mb-3 font-bold">Observações do cadastro</h2><p className="whitespace-pre-wrap text-sm leading-relaxed text-slate-600">{client.notes || 'Sem observações cadastradas.'}</p></Card></div>
  <Card><div className="mb-4 flex items-center justify-between"><div><h2 className="font-bold">Histórico de visitas</h2><p className="text-sm text-slate-500">{visits.length} visita(s) registrada(s)</p></div><History size={21} className="text-brand-600"/></div>{visits.length ? <div className="divide-y divide-slate-100">{visits.reverse().slice(0, 10).map(visit => <button key={visit.id} className="flex w-full items-center gap-3 py-3 text-left hover:bg-brand-50" onClick={() => navigate(`/visits/${visit.id}`)}><div className="grid h-9 w-9 place-items-center rounded-lg bg-slate-100 text-slate-600"><CalendarDays size={17}/></div><div className="min-w-0 flex-1"><div className="font-semibold">{dateLabel(visit.date)}</div><div className="text-xs text-slate-500">{visit.season || 'Safra não informada'}</div></div><StatusBadge status={visit.status}/></button>)}</div> : <p className="py-6 text-center text-sm text-slate-500">Ainda não há visitas para este cliente.</p>}</Card></div>
  {editingClient && <ClientForm client={client} onClose={() => setEditingClient(false)}/>} {propertyForm && <PropertyForm clientId={client.id} onClose={() => setPropertyForm(false)}/>} {fieldForProperty && <FieldForm property={fieldForProperty} onClose={() => setFieldForProperty(null)}/>}</>
}

function PropertyForm({ clientId, onClose }: { clientId: string; onClose: () => void }) { const { refresh, toast } = useApp(); const [form, setForm] = useState<Partial<Property>>({ name: '', state: '' }); const submit = async (event: FormEvent) => {event.preventDefault(); if(!form.name?.trim()) return toast('Informe a identificação da propriedade.', 'error'); await saveProperty({ ...form, name: form.name.trim(), clientId } as NewEntity<Property>); refresh(); toast('Propriedade cadastrada.'); onClose()}; return <Modal title="Nova propriedade" onClose={onClose}><form onSubmit={submit} className="space-y-4"><FieldLabel label="Nome / identificação da fazenda *"><input autoFocus className="input" value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></FieldLabel><div className="grid grid-cols-[1fr_100px] gap-3"><FieldLabel label="Município"><input className="input" value={form.city ?? ''} onChange={e=>setForm({...form,city:e.target.value})}/></FieldLabel><FieldLabel label="UF"><input className="input uppercase" maxLength={2} value={form.state ?? ''} onChange={e=>setForm({...form,state:e.target.value.toUpperCase()})}/></FieldLabel></div><FieldLabel label="Observações"><textarea className="input min-h-20" value={form.notes ?? ''} onChange={e=>setForm({...form,notes:e.target.value})}/></FieldLabel><FormActions onClose={onClose} label="Salvar propriedade"/></form></Modal> }
function FieldForm({ property, onClose }: { property: Property; onClose: () => void }) { const {refresh,toast}=useApp(); const [form,setForm]=useState<Partial<Field>>({name:'',rowSpacingM:0.5}); const submit=async(e:FormEvent)=>{e.preventDefault();if(!form.name?.trim())return toast('Informe a identificação do talhão.','error');await saveField({...form,name:form.name.trim(),propertyId:property.id} as NewEntity<Field>);refresh();toast('Talhão cadastrado.');onClose()};return <Modal title={`Novo talhão — ${property.name}`} onClose={onClose}><form className="space-y-4" onSubmit={submit}><FieldLabel label="Nome ou identificação *"><input autoFocus className="input" value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></FieldLabel><div className="grid grid-cols-2 gap-3"><FieldLabel label="Área (ha)"><input className="input" inputMode="decimal" type="number" min="0" step="0.01" value={form.areaHa ?? ''} onChange={e=>setForm({...form,areaHa:numberOrUndefined(e.target.value)})}/></FieldLabel><FieldLabel label="Espaçamento (m)"><input className="input" inputMode="decimal" type="number" min="0" step="0.01" value={form.rowSpacingM ?? ''} onChange={e=>setForm({...form,rowSpacingM:numberOrUndefined(e.target.value)})}/></FieldLabel></div><FieldLabel label="Observações"><textarea className="input min-h-20" value={form.notes ?? ''} onChange={e=>setForm({...form,notes:e.target.value})}/></FieldLabel><FormActions onClose={onClose} label="Salvar talhão"/></form></Modal> }
function FieldLabel({label,children}:{label:string;children:ReactNode}) {return <label><span className="label">{label}</span>{children}</label>}
function FormActions({onClose,label}:{onClose:()=>void;label:string}) {return <div className="flex justify-end gap-2 pt-2"><button type="button" className="btn-ghost" onClick={onClose}>Cancelar</button><button className="btn-primary">{label}</button></div>}
const numberOrUndefined = (value: string) => value === '' ? undefined : Number(value)

interface EditorPhoto { id: string; filename: string; mimeType: string; caption?: string; position: number; blob?: Blob; createdAt?: string }
type EditorEvaluation = Omit<Evaluation, 'createdAt' | 'updatedAt' | 'syncState'> & { photos: EditorPhoto[]; createdAt?: string }

function blankEvaluation(field: Field, property: Property, clientId: string, visitId: string): EditorEvaluation {
  return { id: uid(), visitId, clientId, propertyId: property.id, fieldId: field.id, culture: 'Soja', phenologicalStage: '', phenologicalCustom: '', nodeCount: undefined, noduleCount: undefined, observations: '', rowSpacingM: field.rowSpacingM, standMeasurements: [{ plants: 0, lengthM: 1 }], standPlantsPerMeter: undefined, standPlantsPerHectare: undefined, standSource: 'calculated', photos: [] }
}

function VisitEditorPage() {
  const { visitId: routeVisitId } = useParams(); const navigate = useNavigate(); const { refresh, toast } = useApp()
  const initialClient = new URLSearchParams(window.location.search).get('client') ?? ''
  const [loaded, setLoaded] = useState(!routeVisitId); const [saving, setSaving] = useState(false); const [reportBlob, setReportBlob] = useState<Blob | null>(null); const [showWhatsApp, setShowWhatsApp] = useState(false); const [whatsAppText, setWhatsAppText] = useState('')
  const [clients, setClients] = useState<Client[]>([]); const [properties, setProperties] = useState<Property[]>([]); const [fields, setFields] = useState<Field[]>([])
  const [visit, setVisit] = useState<Visit>(() => ({ id: routeVisitId ?? uid(), clientId: initialClient, date: today(), status: 'draft', season: '', technicalManager: import.meta.env.VITE_TECHNICAL_MANAGER || '', notes: '', createdAt: now(), updatedAt: now(), syncState: 'pending' }))
  const [evaluations, setEvaluations] = useState<EditorEvaluation[]>([]); const [selection, setSelection] = useState({ clientId: initialClient, propertyId: '', fieldId: '' })
  useEffect(() => { Promise.all([db.clients.orderBy('name').toArray(), db.properties.toArray(), db.fields.toArray()]).then(([a,b,c]) => { setClients(a.filter(item=>!item.archived)); setProperties(b); setFields(c) }) }, [refresh])
  useEffect(() => { if (!routeVisitId) return; getVisitBundle(routeVisitId).then(bundle => { if (!bundle) { toast('Visita não encontrada.', 'error'); navigate('/history'); return } setVisit(bundle.visit); setSelection({ clientId: bundle.visit.clientId, propertyId: '', fieldId: '' }); setEvaluations(bundle.evaluations.map(evaluation => ({ ...evaluation, photos: bundle.photos.filter(photo => photo.evaluationId === evaluation.id).map(photo => ({...photo})) }))); setLoaded(true) }) }, [routeVisitId, navigate, toast])
  const selectedProperties = properties.filter(property => property.clientId === selection.clientId)
  const selectedFields = fields.filter(field => field.propertyId === selection.propertyId)
  const updateSelection = (key: keyof typeof selection, value: string) => setSelection(current => key === 'clientId' ? { clientId:value, propertyId:'', fieldId:'' } : key === 'propertyId' ? { ...current, propertyId:value, fieldId:'' } : {...current, fieldId:value})
  const addEvaluation = () => { const field = fields.find(item => item.id === selection.fieldId); const property = properties.find(item => item.id === selection.propertyId); if (!selection.clientId || !field || !property) return toast('Selecione cliente, propriedade e talhão.', 'error'); if (evaluations.some(item => item.fieldId === field.id)) return toast('Este talhão já foi adicionado à visita.', 'error'); setVisit(current => ({...current, clientId: selection.clientId})); setEvaluations(current => [...current, blankEvaluation(field, property, selection.clientId, visit.id)]); toast('Talhão adicionado à visita.') }
  const updateEvaluation = (id: string, patch: Partial<EditorEvaluation>) => setEvaluations(current => current.map(item => item.id === id ? {...item, ...patch} : item))
  const removeEvaluation = (id: string) => setEvaluations(current => current.filter(item => item.id !== id))
  const savedBundle = () => {
    const timestamp = now(); const finalVisit = {...visit, clientId: selection.clientId || visit.clientId, updatedAt: timestamp, syncState:'pending' as const};
    const finalEvals: Evaluation[] = evaluations.map(item => { const {photos, ...evaluation} = item; return {...evaluation, visitId: finalVisit.id, clientId: finalVisit.clientId, createdAt: item.createdAt ?? timestamp, updatedAt: timestamp, syncState:'pending'} })
    const finalPhotos: VisitPhoto[] = evaluations.flatMap(item => item.photos.map(photo => ({...photo, evaluationId:item.id, createdAt:photo.createdAt ?? timestamp, updatedAt:timestamp, syncState:'pending' as const})))
    return { visit: finalVisit, evaluations: finalEvals, photos: finalPhotos }
  }
  const save = async (status: Visit['status']) => { if (!selection.clientId && !visit.clientId) return toast('Selecione um cliente.', 'error'); if (status === 'finalized' && !evaluations.length) return toast('Adicione pelo menos um talhão antes de finalizar.', 'error'); setSaving(true); try { const bundle = savedBundle(); bundle.visit.status = status; const previous = await db.evaluations.where('visitId').equals(bundle.visit.id).toArray(); for (const oldEvaluation of previous.filter(item => !bundle.evaluations.some(current => current.id === item.id))) await removeEvaluation(oldEvaluation.id); for (const evaluation of bundle.evaluations) { const oldPhotos = await db.photos.where('evaluationId').equals(evaluation.id).toArray(); const currentPhotoIds = new Set(bundle.photos.filter(photo => photo.evaluationId === evaluation.id).map(photo => photo.id)); for (const oldPhoto of oldPhotos.filter(photo => !currentPhotoIds.has(photo.id))) await removePhoto(oldPhoto.id) } await saveVisitBundle(bundle); setVisit(bundle.visit); refresh(); toast(status === 'finalized' ? 'Visita finalizada com sucesso.' : 'Rascunho salvo neste dispositivo.'); if (!routeVisitId) navigate(`/visits/${bundle.visit.id}`, {replace:true}) } finally { setSaving(false) } }
  const context = (): ReportContext | null => { const client = clients.find(item => item.id === (selection.clientId || visit.clientId)); if (!client || !evaluations.length) return null; const converted: Evaluation[] = savedBundle().evaluations; return { visit: {...visit, clientId:client.id}, client, properties, fields, evaluations: converted, photos: savedBundle().photos } }
  const createPdf = async () => { const reportContext = context(); if (!reportContext) return toast('Inclua cliente e ao menos uma avaliação para gerar o relatório.', 'error'); setSaving(true); try { const completeContext = { ...reportContext, photos: await Promise.all(reportContext.photos.map(ensurePhotoBlob)) }; const blob = await createVisitPdf(completeContext); setReportBlob(blob); const filename = `engedrop-${reportContext.client.name.toLowerCase().replace(/[^a-z0-9]+/gi,'-')}-${reportContext.visit.date}.pdf`; await saveReport({visitId:visit.id,evaluationIds:reportContext.evaluations.map(item=>item.id),filename,blob,generatedAt:now()}); refresh(); toast('PDF gerado e salvo no histórico.'); } catch { toast('Não foi possível gerar o PDF.', 'error') } finally { setSaving(false) } }
  const openWhatsApp = () => { const reportContext = context(); if (!reportContext) return toast('Inclua cliente e uma avaliação.', 'error'); setWhatsAppText(buildWhatsAppReport(reportContext)); setShowWhatsApp(true) }
  if (!loaded) return <Loading/>
  const clientForTitle = clients.find(item => item.id === (selection.clientId || visit.clientId))
  return <><button className="btn-ghost mb-3 -ml-2 px-2" onClick={() => navigate(-1)}><ChevronLeft size={18}/>Voltar</button><PageHeader title={routeVisitId ? (visit.status === 'finalized' ? 'Visita finalizada' : 'Editar rascunho') : 'Nova visita técnica'} subtitle={clientForTitle ? `Cliente: ${clientForTitle.name}` : 'Preencha em qualquer ordem; os dados ficam seguros offline.'} actions={<><button className="btn-secondary" disabled={saving} onClick={() => save('draft')}><Check size={17}/>Salvar rascunho</button><button className="btn-primary" disabled={saving} onClick={() => save('finalized')}>{saving && <Loader2 className="animate-spin" size={17}/>}Finalizar visita</button></>}/>
  <div className="grid gap-6 xl:grid-cols-[minmax(0,1fr)_340px]"><div className="space-y-5"><Card><h2 className="mb-4 font-bold">Identificação da visita</h2><div className="grid gap-4 sm:grid-cols-2"><FieldLabel label="Data da visita *"><input className="input" type="date" value={visit.date} onChange={e=>setVisit({...visit,date:e.target.value})}/></FieldLabel><FieldLabel label="Safra"><input className="input" placeholder="Ex.: 2026/27" value={visit.season ?? ''} onChange={e=>setVisit({...visit,season:e.target.value})}/></FieldLabel></div><div className="mt-4 grid gap-4 sm:grid-cols-2"><FieldLabel label="Responsável técnico"><input className="input" value={visit.technicalManager ?? ''} onChange={e=>setVisit({...visit,technicalManager:e.target.value})}/></FieldLabel><FieldLabel label="Cliente *"><select className="select" value={selection.clientId || visit.clientId} onChange={e=>updateSelection('clientId',e.target.value)}><option value="">Selecione o cliente</option>{clients.map(client=><option key={client.id} value={client.id}>{client.name}</option>)}</select></FieldLabel></div><FieldLabel label="Observações gerais da visita"><textarea className="input mt-1 min-h-20" value={visit.notes ?? ''} onChange={e=>setVisit({...visit,notes:e.target.value})}/></FieldLabel></Card>
  <Card><div className="mb-4"><h2 className="font-bold">Adicionar talhão à visita</h2><p className="text-sm text-slate-500">Uma visita pode reunir várias avaliações.</p></div><div className="grid gap-3 md:grid-cols-3"><FieldLabel label="Propriedade"><select className="select" disabled={!selection.clientId} value={selection.propertyId} onChange={e=>updateSelection('propertyId',e.target.value)}><option value="">Selecione</option>{selectedProperties.map(property=><option key={property.id} value={property.id}>{property.name}</option>)}</select></FieldLabel><FieldLabel label="Talhão"><select className="select" disabled={!selection.propertyId} value={selection.fieldId} onChange={e=>updateSelection('fieldId',e.target.value)}><option value="">Selecione</option>{selectedFields.map(field=><option key={field.id} value={field.id}>{field.name}</option>)}</select></FieldLabel><div className="flex items-end"><button className="btn-secondary w-full" onClick={addEvaluation}><Plus size={17}/>Adicionar avaliação</button></div></div>{selection.clientId && !selectedProperties.length && <p className="mt-3 text-sm text-amber-700">Este cliente ainda não possui propriedade/talhão. <button className="underline font-semibold" onClick={()=>navigate(`/clients/${selection.clientId}`)}>Cadastrar agora</button></p>}</Card>
  {evaluations.length ? evaluations.map((evaluation, index) => <EvaluationCard key={evaluation.id} evaluation={evaluation} index={index} field={fields.find(item=>item.id===evaluation.fieldId)} property={properties.find(item=>item.id===evaluation.propertyId)} onChange={patch=>updateEvaluation(evaluation.id,patch)} onRemove={()=>removeEvaluation(evaluation.id)}/>) : <Empty title="Nenhum talhão adicionado" description="Selecione uma propriedade e um talhão acima para registrar a primeira avaliação."/>}</div>
  <aside className="space-y-4 xl:sticky xl:top-6 xl:self-start"><Card><h2 className="font-bold">Ações e relatório</h2><p className="mt-1 text-sm text-slate-500">Gere um documento consolidado ou a mensagem para o produtor.</p><div className="mt-4 grid gap-2"><button className="btn-secondary w-full" disabled={saving || !evaluations.length} onClick={createPdf}><FileText size={17}/>Gerar PDF</button><button className="btn-secondary w-full" disabled={!evaluations.length} onClick={openWhatsApp}><Share2 size={17}/>Relatório WhatsApp</button></div></Card>{routeVisitId && <StoredReports visitId={visit.id}/>}<Card><h3 className="text-sm font-bold">Resumo</h3><dl className="mt-3 space-y-2 text-sm"><div className="flex justify-between"><dt className="text-slate-500">Status</dt><dd><StatusBadge status={visit.status}/></dd></div><div className="flex justify-between"><dt className="text-slate-500">Talhões</dt><dd className="font-semibold">{evaluations.length}</dd></div><div className="flex justify-between"><dt className="text-slate-500">Fotografias</dt><dd className="font-semibold">{evaluations.reduce((sum,item)=>sum+item.photos.length,0)}</dd></div></dl></Card></aside></div>
  {reportBlob && <PdfPreview blob={reportBlob} onClose={()=>setReportBlob(null)} />}{showWhatsApp && <WhatsAppModal text={whatsAppText} onClose={()=>setShowWhatsApp(false)}/>}</>
}

function EvaluationCard({ evaluation, index, field, property, onChange, onRemove }: { evaluation: EditorEvaluation; index: number; field?: Field; property?: Property; onChange: (patch: Partial<EditorEvaluation>) => void; onRemove: () => void }) {
  const stages = stagesForCulture(evaluation.culture); const calculated = calculateStand(evaluation.standMeasurements, evaluation.rowSpacingM)
  const setMeasurements = (standMeasurements: StandMeasurement[]) => { const calc=calculateStand(standMeasurements,evaluation.rowSpacingM); onChange({standMeasurements,standPlantsPerMeter:calc.averagePlantsPerMeter, ...(evaluation.standSource !== 'manual' ? {standPlantsPerHectare:calc.plantsPerHectare} : {})}) }
  const addPhoto = (files: FileList | null) => { if (!files?.length) return; const newest: EditorPhoto[] = Array.from(files).filter(file => file.type.startsWith('image/')).map((file, offset) => ({id:uid(),filename:file.name,mimeType:file.type,blob:file,caption:'',position:evaluation.photos.length+offset})); onChange({photos:[...evaluation.photos,...newest]}) }
  const updatePhoto=(id:string,patch:Partial<EditorPhoto>)=>onChange({photos:evaluation.photos.map(photo=>photo.id===id?{...photo,...patch}:photo)})
  const movePhoto=(id:string,direction:-1|1)=>{const pos=evaluation.photos.findIndex(photo=>photo.id===id);const other=pos+direction;if(other<0||other>=evaluation.photos.length)return;const photos=[...evaluation.photos];[photos[pos],photos[other]]=[photos[other],photos[pos]];onChange({photos:photos.map((photo,position)=>({...photo,position}))})}
  return <Card><div className="mb-5 flex items-start justify-between gap-3"><div><div className="text-xs font-bold uppercase tracking-wide text-brand-600">Avaliação {index+1}</div><h2 className="mt-1 text-lg font-bold">{field?.name ?? 'Talhão'}</h2><p className="text-sm text-slate-500">{property?.name ?? ''}{field?.areaHa ? ` • ${decimal(field.areaHa)} ha` : ''}</p></div><button className="btn-ghost min-h-9 px-2 text-red-600 hover:bg-red-50" title="Remover avaliação" onClick={onRemove}><Trash2 size={18}/></button></div>
  <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3"><FieldLabel label="Cultura *"><input className="input" list={`cultures-${evaluation.id}`} value={evaluation.culture} onChange={e=>onChange({culture:e.target.value,phenologicalStage:''})}/><datalist id={`cultures-${evaluation.id}`}><option>Soja</option><option>Milho</option><option>Feijão</option><option>Algodão</option><option>Trigo</option></datalist></FieldLabel>{stages.length ? <FieldLabel label="Estádio fenológico"><select className="select" value={evaluation.phenologicalStage ?? ''} onChange={e=>onChange({phenologicalStage:e.target.value})}><option value="">Selecione</option>{stages.map(stage=><option key={stage}>{stage}</option>)}</select></FieldLabel> : <FieldLabel label="Estádio fenológico"><input className="input" value={evaluation.phenologicalCustom ?? ''} placeholder="Digite o estádio" onChange={e=>onChange({phenologicalCustom:e.target.value})}/></FieldLabel>}<FieldLabel label="Espaçamento entre linhas (m)"><input className="input" type="number" inputMode="decimal" min="0" step="0.01" value={evaluation.rowSpacingM ?? ''} onChange={e=>{const spacing=numberOrUndefined(e.target.value);const calc=calculateStand(evaluation.standMeasurements,spacing);onChange({rowSpacingM:spacing,standPlantsPerMeter:calc.averagePlantsPerMeter,...(evaluation.standSource !== 'manual'?{standPlantsPerHectare:calc.plantsPerHectare}:{})})}}/></FieldLabel><FieldLabel label="Número de nós"><input className="input" type="number" inputMode="decimal" min="0" value={evaluation.nodeCount ?? ''} onChange={e=>onChange({nodeCount:numberOrUndefined(e.target.value)})}/></FieldLabel><FieldLabel label="Número de nódulos"><input className="input" type="number" inputMode="decimal" min="0" value={evaluation.noduleCount ?? ''} onChange={e=>onChange({noduleCount:numberOrUndefined(e.target.value)})}/></FieldLabel></div>
  <div className="mt-5 rounded-xl border border-brand-100 bg-brand-50/50 p-4"><div className="mb-3 flex items-center justify-between"><div><h3 className="font-bold text-brand-900">Contagem de stand</h3><p className="text-xs text-brand-700">Média ponderada e conversão automática por espaçamento.</p></div><button className="btn-secondary min-h-9 px-3" onClick={()=>setMeasurements([...evaluation.standMeasurements,{plants:0,lengthM:1}])}><Plus size={15}/>Repetição</button></div><div className="space-y-2">{evaluation.standMeasurements.map((measurement, position)=><div key={position} className="grid grid-cols-[30px_1fr_1fr_32px] items-end gap-2"><span className="pb-2 text-sm font-semibold text-brand-700">{position+1}</span><FieldLabel label={position===0?'Plantas':' '}><input className="input bg-white" type="number" min="0" inputMode="decimal" value={measurement.plants} onChange={e=>{const rows=[...evaluation.standMeasurements];rows[position]={...measurement,plants:Number(e.target.value)};setMeasurements(rows)}}/></FieldLabel><FieldLabel label={position===0?'Comprimento (m)':' '}><input className="input bg-white" type="number" min="0.01" step="0.01" inputMode="decimal" value={measurement.lengthM} onChange={e=>{const rows=[...evaluation.standMeasurements];rows[position]={...measurement,lengthM:Number(e.target.value)};setMeasurements(rows)}}/></FieldLabel><button className="btn-ghost min-h-10 px-1 text-red-600" disabled={evaluation.standMeasurements.length===1} onClick={()=>setMeasurements(evaluation.standMeasurements.filter((_,i)=>i!==position))}><Trash2 size={16}/></button></div>)}</div><div className="mt-4 grid gap-3 border-t border-brand-100 pt-4 sm:grid-cols-3"><div><div className="text-xs font-medium text-slate-500">Média</div><div className="font-bold text-brand-900">{decimal(calculated.averagePlantsPerMeter)} plantas/m</div></div><div><div className="text-xs font-medium text-slate-500">População / ha</div><div className="font-bold text-brand-900">{decimal(evaluation.standSource === 'manual' ? evaluation.standPlantsPerHectare : calculated.plantsPerHectare,0)} plantas</div></div><label className="flex items-center gap-2 text-xs font-medium text-slate-600"><input type="checkbox" checked={evaluation.standSource==='manual'} onChange={e=>onChange({standSource:e.target.checked?'manual':'calculated',standPlantsPerHectare:e.target.checked?evaluation.standPlantsPerHectare:calculated.plantsPerHectare})}/>Informar população manualmente</label></div>{evaluation.standSource==='manual'&&<FieldLabel label="Plantas por hectare — valor manual"><input className="input mt-1 bg-white" type="number" min="0" inputMode="numeric" value={evaluation.standPlantsPerHectare??''} onChange={e=>onChange({standPlantsPerHectare:numberOrUndefined(e.target.value),standSource:'manual'})}/></FieldLabel>}<p className="mt-3 text-[11px] text-slate-500">Fórmula: plantas/m × 10.000 ÷ espaçamento (m). Valores manuais são preservados e identificados no relatório.</p></div>
  <FieldLabel label="Observações técnicas"><textarea className="input mt-1 min-h-24" placeholder="Condições da lavoura, pragas, manejo, recomendações..." value={evaluation.observations ?? ''} onChange={e=>onChange({observations:e.target.value})}/></FieldLabel>
  <div className="mt-5 border-t border-slate-100 pt-4"><div className="mb-3 flex flex-wrap items-center justify-between gap-2"><div><h3 className="font-bold">Fotografias</h3><p className="text-xs text-slate-500">Use a câmera ou escolha imagens da galeria. Cada foto possui legenda.</p></div><label className="btn-secondary cursor-pointer"><ImagePlus size={17}/>Adicionar foto<input className="hidden" accept="image/*" capture="environment" multiple type="file" onChange={e=>{addPhoto(e.target.files);e.currentTarget.value=''}}/></label></div>{evaluation.photos.length ? <div className="grid gap-3 sm:grid-cols-2">{evaluation.photos.sort((a,b)=>a.position-b.position).map((photo,position)=><PhotoItem key={photo.id} photo={photo} onChange={patch=>updatePhoto(photo.id,patch)} onDelete={()=>onChange({photos:evaluation.photos.filter(item=>item.id!==photo.id)})} onMove={direction=>movePhoto(photo.id,direction)} canMoveUp={position>0} canMoveDown={position<evaluation.photos.length-1}/>)}</div> : <div className="rounded-xl border border-dashed border-slate-200 py-6 text-center text-sm text-slate-400">Nenhuma foto adicionada.</div>}</div></Card>
}

function PhotoItem({photo,onChange,onDelete,onMove,canMoveUp,canMoveDown}:{photo:EditorPhoto;onChange:(patch:Partial<EditorPhoto>)=>void;onDelete:()=>void;onMove:(direction:-1|1)=>void;canMoveUp:boolean;canMoveDown:boolean}) {const [url,setUrl]=useState<string>();useEffect(()=>{if(!photo.blob)return;const current=URL.createObjectURL(photo.blob);setUrl(current);return()=>URL.revokeObjectURL(current)},[photo.blob]);return <div className="overflow-hidden rounded-xl border border-slate-200 bg-white"><div className="relative aspect-video bg-slate-100">{url?<img src={url} alt={photo.caption||photo.filename} className="h-full w-full object-cover"/>:<div className="grid h-full place-items-center text-sm text-slate-400">Foto sincronizada</div>}<div className="absolute right-2 top-2 flex gap-1"><button className="rounded-lg bg-white/90 p-1.5 text-slate-600 disabled:opacity-40" disabled={!canMoveUp} onClick={()=>onMove(-1)} aria-label="Mover foto para cima">↑</button><button className="rounded-lg bg-white/90 p-1.5 text-slate-600 disabled:opacity-40" disabled={!canMoveDown} onClick={()=>onMove(1)} aria-label="Mover foto para baixo">↓</button><button className="rounded-lg bg-white/90 p-1.5 text-red-600" onClick={onDelete} aria-label="Excluir foto"><Trash2 size={15}/></button></div></div><div className="p-2"><input className="w-full border-0 bg-transparent px-1 py-1 text-sm outline-none placeholder:text-slate-400" placeholder="Adicionar legenda" value={photo.caption??''} onChange={e=>onChange({caption:e.target.value})}/></div></div>}

function StoredReports({ visitId }: { visitId: string }) {
  const { data: reports, loading } = useLoaded(() => db.reports.where('visitId').equals(visitId).reverse().sortBy('generatedAt'), [visitId])
  const { toast } = useApp()
  const download = async (report: Report) => {
    if (report.blob) return downloadBlob(report.blob, report.filename)
    if (report.storagePath && supabase) {
      const { data, error } = await supabase.storage.from('visit-reports').download(report.storagePath)
      if (!error && data) return downloadBlob(data, report.filename)
    }
    toast('O arquivo ainda não está disponível neste dispositivo.', 'error')
  }
  if (loading || !reports?.length) return null
  return <Card><div className="mb-3 flex items-center gap-2"><FileText size={17} className="text-brand-600"/><h3 className="font-bold">Relatórios salvos</h3></div><div className="space-y-2">{reports.map(report => <button key={report.id} onClick={() => download(report)} className="flex w-full items-center gap-2 rounded-lg p-2 text-left text-sm hover:bg-brand-50"><Download size={16} className="text-brand-700"/><span className="min-w-0 flex-1 truncate">{report.filename}</span></button>)}</div></Card>
}

function PdfPreview({blob,onClose}:{blob:Blob;onClose:()=>void}) {const [url,setUrl]=useState('');useEffect(()=>{const current=URL.createObjectURL(blob);setUrl(current);return()=>URL.revokeObjectURL(current)},[blob]);const share=async()=>{const file=new File([blob],'relatorio-engedrop.pdf',{type:'application/pdf'});if(navigator.share&&navigator.canShare?.({files:[file]}))await navigator.share({title:'Relatório Engedrop',files:[file]});else downloadBlob(blob,file.name)};return <Modal title="Pré-visualização do relatório" onClose={onClose} wide><div className="h-[55vh] overflow-hidden rounded-xl border border-slate-200">{url&&<iframe className="h-full w-full" src={url} title="Relatório PDF"/>}</div><div className="mt-4 flex justify-end gap-2"><button className="btn-secondary" onClick={()=>downloadBlob(blob,'relatorio-engedrop.pdf')}><Download size={17}/>Baixar</button><button className="btn-primary" onClick={share}><Share2 size={17}/>Compartilhar</button></div></Modal>}
function WhatsAppModal({text,onClose}:{text:string;onClose:()=>void}) {const {toast}=useApp();const [value,setValue]=useState(text);const copy=async()=>{await navigator.clipboard.writeText(value);toast('Texto copiado.')};const open=()=>window.open(`https://wa.me/?text=${encodeURIComponent(value)}`,'_blank','noopener,noreferrer');return <Modal title="Relatório para WhatsApp" onClose={onClose}><p className="mb-3 text-sm text-slate-500">Revise e edite antes de compartilhar. Campos vazios não são incluídos.</p><textarea className="input min-h-72 font-mono text-xs leading-relaxed" value={value} onChange={e=>setValue(e.target.value)}/><div className="mt-4 flex flex-wrap justify-end gap-2"><button className="btn-secondary" onClick={copy}>Copiar texto</button><button className="btn-primary" onClick={open}><Share2 size={17}/>Abrir WhatsApp</button></div></Modal>}

function HistoryPage() {
  const { data, loading } = useLoaded(async()=>({visits:await db.visits.orderBy('date').reverse().toArray(),clients:await db.clients.toArray(),properties:await db.properties.toArray(),fields:await db.fields.toArray(),evaluations:await db.evaluations.toArray(),reports:await db.reports.toArray()}))
  const navigate=useNavigate(); const [filters,setFilters]=useState({client:'',property:'',field:'',culture:'',season:'',date:''})
  if(loading||!data)return <Loading/>;const filtered=data.visits.filter(visit=>{const related=data.evaluations.filter(item=>item.visitId===visit.id);return (!filters.client||visit.clientId===filters.client)&&(!filters.season||visit.season?.toLowerCase().includes(filters.season.toLowerCase()))&&(!filters.date||visit.date===filters.date)&&(!filters.property||related.some(item=>item.propertyId===filters.property))&&(!filters.field||related.some(item=>item.fieldId===filters.field))&&(!filters.culture||related.some(item=>item.culture.toLowerCase().includes(filters.culture.toLowerCase())))});return <><PageHeader title="Histórico técnico" subtitle="Consulte avaliações, fotos e relatórios anteriores."/><Card className="mb-5"><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3"><FieldLabel label="Cliente"><select className="select" value={filters.client} onChange={e=>setFilters({...filters,client:e.target.value,property:'',field:''})}><option value="">Todos</option>{data.clients.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select></FieldLabel><FieldLabel label="Propriedade"><select className="select" value={filters.property} onChange={e=>setFilters({...filters,property:e.target.value,field:''})}><option value="">Todas</option>{data.properties.filter(item=>!filters.client||item.clientId===filters.client).map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select></FieldLabel><FieldLabel label="Talhão"><select className="select" value={filters.field} onChange={e=>setFilters({...filters,field:e.target.value})}><option value="">Todos</option>{data.fields.filter(item=>!filters.property||item.propertyId===filters.property).map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select></FieldLabel><FieldLabel label="Cultura"><input className="input" placeholder="Ex.: soja" value={filters.culture} onChange={e=>setFilters({...filters,culture:e.target.value})}/></FieldLabel><FieldLabel label="Safra"><input className="input" placeholder="Ex.: 2026/27" value={filters.season} onChange={e=>setFilters({...filters,season:e.target.value})}/></FieldLabel><FieldLabel label="Data"><input className="input" type="date" value={filters.date} onChange={e=>setFilters({...filters,date:e.target.value})}/></FieldLabel></div></Card>{filtered.length?<div className="space-y-3">{filtered.map(visit=>{const ev=data.evaluations.filter(item=>item.visitId===visit.id);const client=data.clients.find(item=>item.id===visit.clientId);return <button key={visit.id} onClick={()=>navigate(`/visits/${visit.id}`)} className="card flex w-full items-center gap-3 text-left transition hover:border-brand-200"><div className="grid h-11 w-11 place-items-center rounded-xl bg-brand-50 text-brand-700"><ClipboardList size={21}/></div><div className="min-w-0 flex-1"><div className="font-bold">{client?.name??'Cliente removido'}</div><div className="truncate text-sm text-slate-500">{dateLabel(visit.date)} • {ev.map(item=>data.fields.find(field=>field.id===item.fieldId)?.name).filter(Boolean).join(', ')||'Sem talhão'}{visit.season?` • ${visit.season}`:''}</div></div><div className="hidden text-right text-xs text-slate-500 sm:block"><div>{ev.length} avaliação(ões)</div><div>{data.reports.filter(report=>report.visitId===visit.id).length} PDF(s)</div></div><StatusBadge status={visit.status}/></button>})}</div>:<Empty title="Nenhuma visita encontrada" description="Ajuste os filtros ou comece uma nova visita." action={<button className="btn-primary" onClick={()=>navigate('/visits/new')}><Plus size={17}/>Nova visita</button>}/>}</>
}

function SettingsPage() {const {toast,refresh}=useApp();const [email,setEmail]=useState('');const [password,setPassword]=useState('');const [user,setUser]=useState<string | null>(null);const [loading,setLoading]=useState(false);useEffect(()=>{supabase?.auth.getUser().then(({data})=>setUser(data.user?.email??null))},[]);const signIn=async(e:FormEvent)=>{e.preventDefault();if(!supabase)return;setLoading(true);const {data,error}=await supabase.auth.signInWithPassword({email,password});setLoading(false);if(error)return toast(error.message,'error');setUser(data.user?.email??email);await pullRemote().catch(()=>undefined);refresh();toast('Login realizado e dados atualizados.')};const signOut=async()=>{await supabase?.auth.signOut();setUser(null);toast('Sessão encerrada neste dispositivo.')};return <><PageHeader title="Configurações" subtitle="Conectividade, segurança e dados da aplicação."/><div className="grid gap-6 lg:grid-cols-2"><Card><div className="flex items-start gap-3"><div className={`grid h-10 w-10 place-items-center rounded-xl ${supabaseConfigured?'bg-brand-100 text-brand-700':'bg-amber-100 text-amber-700'}`}>{supabaseConfigured?<Cloud size={20}/>:<CloudOff size={20}/>}</div><div><h2 className="font-bold">Sincronização Supabase</h2><p className="mt-1 text-sm text-slate-500">{supabaseConfigured?'O projeto está configurado para sincronizar via nuvem privada.':'O aplicativo está em modo local. Todos os dados ficam neste navegador com IndexedDB.'}</p></div></div>{!supabaseConfigured?<div className="mt-4 rounded-xl bg-amber-50 p-4 text-sm text-amber-900">Copie <code>.env.example</code> para <code>.env</code>, informe a URL e a chave anônima do Supabase, aplique a migration e reinicie o aplicativo. A chave de serviço nunca deve ser usada no frontend.</div>:user?<div className="mt-4 rounded-xl bg-brand-50 p-4"><div className="text-sm">Conectado como <strong>{user}</strong></div><button className="btn-secondary mt-3" onClick={signOut}>Sair</button></div>:<form className="mt-4 space-y-3" onSubmit={signIn}><FieldLabel label="E-mail corporativo"><input className="input" type="email" required value={email} onChange={e=>setEmail(e.target.value)}/></FieldLabel><FieldLabel label="Senha"><input className="input" type="password" required value={password} onChange={e=>setPassword(e.target.value)}/></FieldLabel><button className="btn-primary" disabled={loading}>{loading&&<Loader2 size={16} className="animate-spin"/>}Entrar para sincronizar</button></form>}</Card><Card><h2 className="font-bold">Uso offline</h2><p className="mt-2 text-sm leading-relaxed text-slate-600">O PWA mantém as telas disponíveis após a primeira abertura. Cadastros, rascunhos, avaliações e imagens são persistidos localmente antes de qualquer envio. Ao ficar online, os registros usam IDs únicos e são enviados em fila, sem criar duplicatas.</p><div className="mt-4 rounded-xl bg-slate-50 p-3 text-sm"><strong>Status da conexão:</strong> {isOnline()?'online':'offline'}<br/><strong>Armazenamento:</strong> IndexedDB local</div></Card><Card><h2 className="font-bold">Identidade visual</h2><p className="mt-2 text-sm text-slate-600">A marca exibida é um marcador institucional temporário em SVG. Para aplicar a logomarca oficial, substitua <code>public/icon-192.svg</code>, <code>public/icon-512.svg</code> e a marca no cabeçalho do PDF conforme o guia de marca da Engedrop.</p></Card><Card><h2 className="font-bold">Proteção de dados</h2><p className="mt-2 text-sm text-slate-600">O banco e os buckets são privados por RLS. Somente contas previamente liberadas como colaboradoras ativas podem consultar ou gravar dados. Clientes não recebem credenciais ou acesso ao aplicativo.</p></Card></div></>}
function Loading(){return <div className="grid min-h-48 place-items-center text-brand-600"><Loader2 className="animate-spin" size={28}/></div>}

export default function App() { return <AppShell/> }
